const { PGlite } = require('@electric-sql/pglite');
const { PrismaClient } = require('@prisma/client');
const express = require('express');

const pglite = new PGlite();

const adapter = {
  flavor: 'postgres',
  async connect() {
    return this;
  },
  async queryRaw(params) {
    const res = await pglite.query(params.sql, params.args);
    return {
      columnNames: res.fields.map(f => f.name),
      columnTypes: res.fields.map(f => f.dataTypeID),
      rows: res.rows.map(r => Object.values(r)),
    };
  },
  async executeRaw(params) {
    const res = await pglite.query(params.sql, params.args);
    return res.affectedRows || 0;
  },
};

const prisma = new PrismaClient({ adapter });
const app = express();
app.use(express.json());

